import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Plan 0010 — Search performance","description":"","frontmatter":{"title":"Plan 0010 — Search performance","type":"plan","date":"2026-10-14T00:00:00.000Z","status_note":"accepted"},"headers":[],"relativePath":"graphopt/project/plans/0010-performance.md","filePath":"vendored/graphopt/project/plans/0010-performance.md"}`),a={name:`graphopt/project/plans/0010-performance.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-0010-—-search-performance" tabindex="-1">Plan 0010 — Search performance <a class="header-anchor" href="#plan-0010-—-search-performance" aria-label="Permalink to “Plan 0010 — Search performance”">​</a></h1><p>Depends on <strong>0006</strong> (API seam), <strong>0007</strong> (backend abstraction), <strong>0008</strong> (package split), <strong>0009</strong> (composable rule sets).</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Make the search fast <strong>without changing what it finds</strong> (except where a change is explicit and opt-in). Three levers, biggest first:</p><ol><li><strong>Search less</strong> — compile patterns, target the scan, schedule rules, saturate lazily.</li><li><strong>Do less per match</strong> — persistent bindings, streaming, an incremental congruence closure.</li><li><strong>Leave Python</strong> — a native (Rust) core behind the same API.</li></ol><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to “Non-goals”">​</a></h2><ul><li><strong>Rule <em>sets</em></strong> — which laws exist, how they compose, and which preset is the default — are <strong>0009</strong>&#39;s job. This plan consumes a rule set; it does not define one.</li><li><strong>Completeness.</strong> Full equality saturation is exponential (EXPSPACE-hard in the worst case). Every lever here that trades completeness for speed is <strong>opt-in</strong> and documented.</li></ul><h2 id="lever-1-—-search-less" tabindex="-1">Lever 1 — search less <a class="header-anchor" href="#lever-1-—-search-less" aria-label="Permalink to “Lever 1 — search less”">​</a></h2><h3 id="_1a-compiled-matcher-biggest-single-win" tabindex="-1">1a. Compiled matcher (biggest single win) <a class="header-anchor" href="#_1a-compiled-matcher-biggest-single-win" aria-label="Permalink to “1a. Compiled matcher (biggest single win)”">​</a></h3><p>Today <code>_match</code> interprets the LHS pattern tree on every candidate match (<code>core.py:500</code>). Compile each rule&#39;s LHS <strong>once</strong>, at rule load, into a matcher:</p><ul><li>a <strong>discrimination net</strong> keyed by <code>(root op, arity, child ops)</code> so a class dispatches straight to the applicable rules;</li><li>the compiled node is a closure/decision tree — no per-match tree walk, no <code>isinstance</code> ladder, no <code>_pattern_attrs</code> recomputation.</li></ul><p>Preserves semantics exactly: attribute metavariables (<code>$attr:</code>), shared-metavariable consistency, <code>max_results</code>.</p><h3 id="_1b-targeted-eligibility" tabindex="-1">1b. Targeted eligibility <a class="header-anchor" href="#_1b-targeted-eligibility" aria-label="Permalink to “1b. Targeted eligibility”">​</a></h3><p><code>_candidate_classes</code> filters by the LHS head op via <code>_op_classes</code> (<code>core.py:924</code>). Extend the eligibility key to <strong>arity</strong> and <strong>child-op constraints</strong> from the compiled pattern, so a rule never scans a class that cannot match its head shape.</p><h3 id="_1c-rule-scheduling" tabindex="-1">1c. Rule scheduling <a class="header-anchor" href="#_1c-rule-scheduling" aria-label="Permalink to “1c. Rule scheduling”">​</a></h3><p>Order rules within an iteration: cheap/filtering rules first (they shrink classes and enable early merges), closure-generating rules last and budgeted. The scheduler is data — a priority per rule — supplied by the rule set (0009). comm/assoc stay available but are <strong>opt-in, never default</strong>: they are the Catalan blowup, and 0009&#39;s default preset excludes them.</p><h3 id="_1d-lazy-best-first-saturation-opt-in" tabindex="-1">1d. Lazy / best-first saturation (opt-in) <a class="header-anchor" href="#_1d-lazy-best-first-saturation-opt-in" aria-label="Permalink to “1d. Lazy / best-first saturation (opt-in)”">​</a></h3><p>Instead of running to the fixed point, extract <strong>every iteration</strong> and stop when the cost stops improving for <code>patience</code> iterations (default e.g. 3). Most wins land in the first few iterations.</p><ul><li>Exposed as <code>search(..., stop=&quot;fixed_point&quot; | &quot;improving&quot;, patience=3)</code>.</li><li><code>&quot;improving&quot;</code> is a <strong>heuristic</strong> — it can stop before the true optimum. The default stays <strong><code>&quot;fixed_point&quot;</code></strong>; <code>&quot;improving&quot;</code> is opt-in, and is only reconsidered as the default with corpus evidence (no quality loss on <code>bench/</code>) — a data decision, not a design one.</li></ul><h2 id="lever-2-—-do-less-per-match" tabindex="-1">Lever 2 — do less per match <a class="header-anchor" href="#lever-2-—-do-less-per-match" aria-label="Permalink to “Lever 2 — do less per match”">​</a></h2><h3 id="_2a-persistent-bindings-in-place-backtracking" tabindex="-1">2a. Persistent bindings / in-place backtracking <a class="header-anchor" href="#_2a-persistent-bindings-in-place-backtracking" aria-label="Permalink to “2a. Persistent bindings / in-place backtracking”">​</a></h3><p><code>_match</code> copies <code>dict(subst)</code> at every recursion level and every branch (<code>core.py:540-602</code>). Replace with a single mutable binding table plus a <strong>trail</strong> (bind on descend, undo on backtrack). Removes the dominant allocation in the hot loop.</p><h3 id="_2b-stream-matches" tabindex="-1">2b. Stream matches <a class="header-anchor" href="#_2b-stream-matches" aria-label="Permalink to “2b. Stream matches”">​</a></h3><p><code>matches</code> materialises <code>list[dict]</code> per class per rule (<code>core.py:486</code>). Make it a <strong>generator</strong>; <code>apply_rule</code> consumes the stream and applies as it goes, so an over-large enumeration is never built. <code>max_results</code> still caps it.</p><h3 id="_2c-incremental-congruence-closure" tabindex="-1">2c. Incremental congruence closure <a class="header-anchor" href="#_2c-incremental-congruence-closure" aria-label="Permalink to “2c. Incremental congruence closure”">​</a></h3><p><code>_close_congruence</code> scans <strong>every</strong> class and node each round, building an <code>owner</code> dict of all enodes (<code>core.py:703</code>). Replace with a <strong>worklist</strong>: only enodes whose children changed since the last closure are re-keyed, so the pass is proportional to the delta, not to <code>E</code>.</p><h2 id="lever-3-—-native-core-rust" tabindex="-1">Lever 3 — native core (Rust) <a class="header-anchor" href="#lever-3-—-native-core-rust" aria-label="Permalink to “Lever 3 — native core (Rust)”">​</a></h2><p>Port the <strong>search core</strong> to Rust, behind the same Python API:</p><ul><li>union-find, enode storage, matching (compiled), rebuild / congruence, and greedy extraction;</li><li>PyO3 bindings.</li></ul><p><strong>Scope boundary — search only.</strong> The proof / certificate layer (<code>_track</code>, <code>_merge_log</code>, <code>_applications</code>, <code>certificate</code>, <code>verify_certificate</code>) and the carrier non-local passes (which mutate the graph through <code>union(witness=...)</code>) stay in <strong>Python</strong>. A run that needs a certificate uses the Python engine, or the native core searches and the certificate is produced by the Python path. Porting the proof machinery is explicitly out of scope.</p><p><strong>Not parallel (yet).</strong> Rules within an iteration are applied <em>sequentially</em> against a mutating graph — rule B matches what rule A just changed — so naive parallel rule application changes semantics. Parallelism is deferred; if pursued it needs a snapshot-per-rule + deterministic-merge discipline, specified on its own.</p><p>Shape:</p><ul><li><code>catopt_core</code> stays <strong>pure-Python, zero-dependency</strong> — it remains the reference implementation, the correctness oracle, and the default engine.</li><li>A new optional distribution <strong><code>catopt-native</code></strong> (<code>catopt_native</code>) implements the same <code>EGraph</code> <strong>search</strong> surface behind an <strong><code>Engine</code></strong> protocol defined in <code>catopt_core</code>.</li><li><strong>Engine selection is explicit.</strong> <code>Optimizer(..., engine=...)</code> / <code>search(..., engine=...)</code>; the default is the pure-Python reference. The native engine is <strong>never auto-detected</strong> — installing the wheel must not silently switch engines. <code>stats[&quot;engine&quot;]</code> records which ran.</li><li><code>tests/egglog_oracle.py</code> is the existing differential oracle; the native core is validated against the Python one on extracted <strong>terms and costs</strong>. Certificates stay a Python-engine concern.</li></ul><p>This is the only <strong>step change</strong> (10–100×) — on the search phase only; levers 1–2 are 2–10×.</p><h2 id="correctness-oracle" tabindex="-1">Correctness oracle <a class="header-anchor" href="#correctness-oracle" aria-label="Permalink to “Correctness oracle”">​</a></h2><p>Every lever must be checked against a known-good path:</p><ul><li>compiled matcher vs interpreted matcher — identical substitution sets on the property-test corpus;</li><li>streaming vs list — identical applications;</li><li>incremental congruence vs full closure — identical canonical classes;</li><li>lazy saturation — documented as heuristic, never asserted equal;</li><li>native vs Python — identical extracted term and cost (certificates are produced by the Python engine, not the native core).</li></ul><h2 id="measurement" tabindex="-1">Measurement <a class="header-anchor" href="#measurement" aria-label="Permalink to “Measurement”">​</a></h2><p>Profile before changing anything: <code>bench/suites/search/search_efficiency.py</code> plus <code>cProfile</code> on a real model (the demo block and a stacked transformer block). Record per-phase time (match / union / rebuild / extract) so each lever is attributed. Add a scaling table (enodes vs seconds) to the bench results.</p><h2 id="execution-stages" tabindex="-1">Execution stages <a class="header-anchor" href="#execution-stages" aria-label="Permalink to “Execution stages”">​</a></h2><p>Each stage lands independently, suite green, oracle-verified.</p><ol><li><strong>Compiled matcher</strong> (1a) — pure Python.</li><li><strong>Matcher allocations + streaming</strong> (2a, 2b).</li><li><strong>Incremental congruence</strong> (2c).</li><li><strong>Targeted eligibility</strong> (1b).</li><li><strong>Rule scheduling</strong> (1c) — consumes 0009&#39;s priority data.</li><li><strong>Lazy saturation</strong> (1d) — opt-in, off by default.</li><li><strong>Native core</strong> (3) — <code>catopt-native</code>, PyO3, differential oracle.</li></ol><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to “Risks”">​</a></h2><ul><li><strong>Semantic drift in the compiled matcher</strong> — attribute metavars, shared-metavar consistency, and <code>max_results</code> are easy to get subtly wrong; the property corpus is the guard.</li><li><strong>Lazy saturation changes results</strong> — it must stay opt-in and be reported in <code>stats</code> (e.g. <code>stats[&quot;stop&quot;]</code>, <code>stats[&quot;improved&quot;]</code>).</li><li><strong>Native build/CI</strong> — wheels per platform (maturin), a <code>--torch-backend cpu</code>-style matrix entry, and keeping the pure-Python fallback working everywhere.</li><li><strong>Native scope creep</strong> — the temptation to port proofs, certificates and the non-local passes. Explicitly out of scope; the native core is the search loop only.</li><li><strong>Two implementations to maintain</strong> — mitigated by the oracle: the Python core is the spec, the native core the accelerator.</li></ul><h2 id="decisions-resolved" tabindex="-1">Decisions (resolved) <a class="header-anchor" href="#decisions-resolved" aria-label="Permalink to “Decisions (resolved)”">​</a></h2><ol><li><strong>Native package</strong> — <code>catopt-native</code> / <code>catopt_native</code>. Role-named, not language-named (a future rewrite in another language does not invalidate it).</li><li><strong>Engine selection</strong> — an <code>Engine</code> protocol in <code>catopt_core</code>, passed explicitly (<code>Optimizer(..., engine=...)</code> / <code>search(..., engine=...)</code>). The pure-Python core is the default (the library&#39;s own reference, not an external assumption). The native engine is <strong>never auto-detected</strong>; <code>stats[&quot;engine&quot;]</code> records which ran.</li><li><strong>Default <code>stop</code></strong> — <code>&quot;fixed_point&quot;</code>. <code>&quot;improving&quot;</code> is opt-in and revisited only with corpus evidence.</li></ol>`,46)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};